prompt --application/shared_components/navigation/lists/administration_application
begin
wwv_flow_imp_shared.create_list(
 p_id=>wwv_flow_imp.id(40767329998336811)
,p_name=>'Administration - Application'
,p_static_id=>'admin-application'
,p_list_type=>'SQL_QUERY'
,p_list_query=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- One entry per feature of this group that the user may open and that has a page in this application',
'-- (release 72: the feature''s home page here, else its first tab here; the shared setup is IT''s, in COMMON).',
'-- release 73: plus each common function IT lets KYC manage (Setup dialog, page 98), as its own entry',
'select lvl, label, target, is_current, image, image_attribute, image_alt, a01',
'  from (',
'select null                                    as lvl,',
'       m.feature_name                          as label,',
'       apex_page.get_url(p_page => t.page_id)  as target,',
'       ''NO''                                    as is_current,',
'       m.icon_css                              as image,',
'       null                                    as image_attribute,',
'       null                                    as image_alt,',
'       m.description                           as a01,',
'       m.display_sequence                      as seq',
'  from xxfnd_admin_menu_v m',
'  cross apply (select min(fp.page_id) keep (dense_rank first order by',
'                          case when fp.page_id = m.home_page_id then 0 else 1 end,',
'                          fp.tab_sequence nulls last, fp.page_id) as page_id',
'                 from xxfnd_feature_pages fp',
'                where fp.app_alias = :APP_ALIAS and fp.feature_code = m.feature_code',
'                  and xxfnd_admin_scope_pkg.local_page(fp.page_id) = ''Y'') t',
' where m.feature_group = ''APPLICATION''',
'   and t.page_id is not null',
'union all',
'select null,',
'       m.feature_name || '' (shared setup)'',',
'       xxfnd_admin_scope_pkg.delegated_url(m.feature_code),',
'       ''NO'',',
'       m.icon_css,',
'       null,',
'       null,',
'       m.description,',
'       m.display_sequence + 0.5',
'  from xxfnd_admin_menu_v m',
' where m.feature_group = ''APPLICATION''',
'   and xxfnd_admin_scope_pkg.delegated_url(m.feature_code) is not null',
'       )',
' order by seq'))
);
end;
/
prompt --application/shared_components/navigation/lists/administration_basic_setup
begin
wwv_flow_imp_shared.create_list(
 p_id=>wwv_flow_imp.id(40767015129336810)
,p_name=>'Administration - Basic Setup'
,p_static_id=>'admin-basic-setup'
,p_list_type=>'SQL_QUERY'
,p_list_query=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- One entry per feature of this group that the user may open and that has a page in this application',
'-- (release 72: the feature''s home page here, else its first tab here; the shared setup is IT''s, in COMMON).',
'-- release 73: plus each common function IT lets KYC manage (Setup dialog, page 98), as its own entry',
'select lvl, label, target, is_current, image, image_attribute, image_alt, a01',
'  from (',
'select null                                    as lvl,',
'       m.feature_name                          as label,',
'       apex_page.get_url(p_page => t.page_id)  as target,',
'       ''NO''                                    as is_current,',
'       m.icon_css                              as image,',
'       null                                    as image_attribute,',
'       null                                    as image_alt,',
'       m.description                           as a01,',
'       m.display_sequence                      as seq',
'  from xxfnd_admin_menu_v m',
'  cross apply (select min(fp.page_id) keep (dense_rank first order by',
'                          case when fp.page_id = m.home_page_id then 0 else 1 end,',
'                          fp.tab_sequence nulls last, fp.page_id) as page_id',
'                 from xxfnd_feature_pages fp',
'                where fp.app_alias = :APP_ALIAS and fp.feature_code = m.feature_code',
'                  and xxfnd_admin_scope_pkg.local_page(fp.page_id) = ''Y'') t',
' where m.feature_group = ''BASIC_SETUP''',
'   and t.page_id is not null',
'union all',
'select null,',
'       m.feature_name || '' (shared setup)'',',
'       xxfnd_admin_scope_pkg.delegated_url(m.feature_code),',
'       ''NO'',',
'       m.icon_css,',
'       null,',
'       null,',
'       m.description,',
'       m.display_sequence + 0.5',
'  from xxfnd_admin_menu_v m',
' where m.feature_group = ''BASIC_SETUP''',
'   and xxfnd_admin_scope_pkg.delegated_url(m.feature_code) is not null',
'       )',
' order by seq'))
);
end;
