prompt --application/shared_components/navigation/lists/case_sections
begin
wwv_flow_imp_shared.create_list(
 p_id=>wwv_flow_imp.id(40768871054336811)
,p_name=>'Case Sections'
,p_static_id=>'case-sections'
,p_list_type=>'SQL_QUERY'
,p_list_query=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- release 74 (R5, R11): the case screen''s section menu as a dynamic list (was HTML from PL/SQL); the state of',
'-- each section (done / warning / to do) from XXCMP_CASE_PKG.SECTION_STATE, shown as the icon and item class',
'select null as lvl,',
'       s.n || '' '' || xxfnd_util_pkg.lookup_meaning(''CASE_SECTION'', s.code) as label,',
'       apex_page.get_url(p_page => 211, p_items => ''P211_CASE_ID,P211_TASK_ID,P211_SECTION'',',
'                         p_values => :P211_CASE_ID || '','' || :P211_TASK_ID || '','' || s.code) as target,',
'       case when s.code = :P211_SECTION then ''YES'' else ''NO'' end as is_current,',
'       case when s.code = :P211_SECTION then ''fa-dot-circle-o''',
'            when s.state = ''DONE'' then ''fa-check-circle''',
'            when s.state = ''WARN'' then ''fa-exclamation-triangle''',
'            else ''fa-circle-o'' end as image,',
'       null as image_attribute,',
'       null as image_alt,',
'       null as a01,',
'       null as a02,',
'       ''kyc-case-nav-item is-'' || lower(s.state) || case when s.code = :P211_SECTION then '' is-current'' end as a03',
'  from (select t.column_value as code, rownum as n,',
'               xxcmp_case_pkg.section_state(:P211_CASE_ID, t.column_value) as state',
'          from table(apex_string.split(xxcmp_case_pkg.sections, '':'')) t) s',
' order by s.n'))
);
end;
/
prompt --application/shared_components/navigation/lists/feature_tabs
begin
wwv_flow_imp_shared.create_list(
 p_id=>wwv_flow_imp.id(40767489981336811)
,p_name=>'Feature Tabs'
,p_static_id=>'feature-tabs'
,p_list_type=>'SQL_QUERY'
,p_list_query=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- The list pages of the current page''s feature, as tabs (XXFND_FEATURE_PAGES.TAB_LABEL).',
'select null                                  as lvl,',
'       fp.tab_label                          as label,',
'       xxfnd_admin_scope_pkg.setup_page_url(fp.page_id) as target,',
'       case when fp.page_id = :APP_PAGE_ID then ''YES'' else ''NO'' end as is_current',
'  from xxfnd_feature_pages fp',
' where fp.app_alias = :APP_ALIAS',
'   and fp.tab_label is not null',
'   -- release 72: only tabs whose page is in this application',
'   and xxfnd_admin_scope_pkg.local_page(fp.page_id) = ''Y''',
'   and fp.feature_code = (select c.feature_code from xxfnd_feature_pages c',
'                           where c.app_alias = :APP_ALIAS and c.page_id = :APP_PAGE_ID)',
' order by fp.tab_sequence'))
);
end;
