,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- release 74 (R14): identity document checks of the individual (manual)',
'select v.id_verification_id,',
'       xxfnd_util_pkg.lookup_meaning(''ID_DOCUMENT_TYPE'', v.document_type) as document_type,',
'       v.document_number,',
'       xxfnd_util_pkg.lookup_meaning(''JURISDICTION'', v.issuing_country) as issuing_country,',
'       v.expiry_date,',
'       xxfnd_util_pkg.lookup_meaning(''ID_VERIFICATION_METHOD'', v.verification_method) as verification_method,',
'       xxfnd_util_pkg.lookup_meaning(''ID_VERIFICATION_RESULT'', v.verification_result) as verification_result,',
'       decode(v.verification_result, ''VERIFIED'', ''success'', ''NOT_VERIFIED'', ''danger'', ''warning'') as result_tone,',
'       xxfnd_ui_pkg.person_name(v.verified_by) as verified_by,',
'       v.verified_date,',
'       case when (:APP_PAGE_ID = 21 or (:APP_PAGE_ID = 211 and :P211_SECTION <> ''REVIEW'')) and xxcmp_party_pkg.can_record_verification(:P0_SUMMARY_PARTY_ID, case when :APP_PAGE_ID = 211 then :P211_CASE_ID end) = ''Y'' then apex_page.get_url(p_page => 2'
||'6, p_items => ''P26_ID_VERIFICATION_ID,P26_PARTY_ID,P26_CASE_ID'', p_values => to_char(v.id_verification_id) || '','' || :P0_SUMMARY_PARTY_ID || '','' || v.case_id, p_clear_cache => ''26'') end as edit_url',
'  from xxcmp_party_id_verifications v',
' where v.party_id = :P0_SUMMARY_PARTY_ID',
' order by v.verified_date desc, v.id_verification_id desc'))
,p_display_when_condition=>'(:APP_PAGE_ID = 21 or (:APP_PAGE_ID = 211 and :P211_SECTION in (''PARTY'', ''REVIEW''))) and :P0_SUMMARY_PARTY_ID is not null and xxfnd_privilege_pkg.has_privilege(''PARTIES'', ''VIEW'') and xxcmp_party_pkg.party_type(:P0_SUMMARY_PARTY_ID) = ''PERSON'''
,p_display_when_cond2=>'PLSQL'
,p_display_condition_type=>'EXPRESSION'
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P0_SUMMARY_PARTY_ID,P0_REQUEST_ID'
,p_lazy_loading=>false
,p_query_row_template=>2540130677583398057
