wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(40799708104337197)
,p_name=>'Registry Checks'
,p_static_id=>'party-registry-checks'
,p_region_name=>'party_registry_checks'
,p_template=>4073835273271169698
,p_display_sequence=>30
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#:t-Report--stretch:t-Report--staticRowColors:t-Report--rowHighlight:t-Report--horizontalBorders'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- release 74 (R14): company registry (KYB) checks of the organisation (manual now, from a provider later)',
'select r.registry_check_id,',
'       r.registry_name,',
'       r.external_reference,',
'       xxfnd_util_pkg.lookup_meaning(''DATA_SOURCE'', r.source) as source,',
'       xxfnd_util_pkg.lookup_meaning(''REGISTRATION_STATUS'', r.registration_status) as registration_status,',
'       xxfnd_util_pkg.lookup_meaning(''REGISTRY_CHECK_RESULT'', r.check_result) as check_result,',
'       decode(r.check_result, ''MATCH'', ''success'', ''MISMATCH'', ''danger'', ''warning'') as result_tone,',
'       xxfnd_ui_pkg.person_name(r.checked_by) as checked_by,',
'       r.checked_date,',
'       case when r.source = ''API'' then nvl(xxfnd_ui_pkg.person_name(r.reviewed_by), ''Not reviewed'') end as reviewed_by,',
'       case r.changed_by_person_flag when ''Y'' then ''Changed by a person'' end as changed,',
'       case when (:APP_PAGE_ID = 21 or (:APP_PAGE_ID = 211 and :P211_SECTION <> ''REVIEW'')) and xxcmp_party_pkg.can_record_verification(:P0_SUMMARY_PARTY_ID, case when :APP_PAGE_ID = 211 then :P211_CASE_ID end) = ''Y'' then apex_page.get_url(p_page => 2'
||'7, p_items => ''P27_REGISTRY_CHECK_ID,P27_PARTY_ID,P27_CASE_ID'', p_values => to_char(r.registry_check_id) || '','' || :P0_SUMMARY_PARTY_ID || '','' || r.case_id, p_clear_cache => ''27'') end as edit_url',
'  from xxcmp_party_registry_checks r',
' where r.party_id = :P0_SUMMARY_PARTY_ID',
' order by r.checked_date desc, r.registry_check_id desc'))
,p_display_when_condition=>'(:APP_PAGE_ID = 21 or (:APP_PAGE_ID = 211 and :P211_SECTION in (''PARTY'', ''REVIEW''))) and :P0_SUMMARY_PARTY_ID is not null and xxfnd_privilege_pkg.has_privilege(''PARTIES'', ''VIEW'') and xxcmp_party_pkg.party_type(:P0_SUMMARY_PARTY_ID) = ''ORGANIZATION'''
,p_display_when_cond2=>'PLSQL'
,p_display_condition_type=>'EXPRESSION'
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P0_SUMMARY_PARTY_ID,P0_REQUEST_ID'
,p_lazy_loading=>false
,p_query_row_template=>2540130677583398057
,p_query_num_rows=>20
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_no_data_found=>'No registry check yet.'
,p_query_num_rows_type=>'ROW_RANGES_WITH_LINKS'
,p_pagination_display_position=>'BOTTOM_RIGHT'
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'N'
,p_comment=>'Release 74 (R14): company registry (KYB) checks of an organisation - by hand now, from a registry provider later (Compliance only).'
);
