wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(40794147648337195)
,p_name=>'Request Header'
,p_static_id=>'record-header'
,p_region_name=>'record_header'
,p_template=>4502917002193490937
,p_display_sequence=>1
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#:t-Report--stretch'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- release 74 (R11): the header card from data (no HTML from PL/SQL); data security applies',
unistr('select r.request_number || '' \00B7 '' || r.party_name as title,'),
'       xxfnd_ui_pkg.status_label(''REQUEST'', r.request_status) as status_label,',
'       xxfnd_ui_pkg.status_tone(''REQUEST'', r.request_status) as status_tone,',
'       case when xxcmp_request_pkg.kyc_required(r.request_id) = ''Yes'' then ''KYC required'' end as kyc_label,',
'       case when r.intake_score is not null',
unistr('            then ''Score '' || r.intake_score || case when r.intake_critical_flag = ''Y'' then '' \00B7 critical answer'' end'),
'       end as score_label,',
'       case when r.intake_critical_flag = ''Y'' then ''danger'' else ''neutral'' end as score_tone,',
'       (select max(c.case_number) from xxcmp_cases c where c.request_id = r.request_id) as case_number,',
'       rtrim(xxfnd_util_pkg.lookup_meaning(''KYC_REQUEST_TYPE'', r.request_type)',
unistr('             || nvl2(r.business_relationship, '' \00B7 '' || xxfnd_util_pkg.lookup_meaning(''BUSINESS_RELATIONSHIP'', r.business_relationship), null)'),
unistr('             || nvl2(r.requesting_department, '' \00B7 '' || xxfnd_util_pkg.lookup_meaning(''REQUESTING_DEPARTMENT'', r.requesting_department), null),'),
unistr('             '' \00B7'') as type_line,'),
'       r.requester_user_name as requester,',
'       xxfnd_ui_pkg.person_name(r.requester_user_name) as requester_name,',
'       w.pending_user,',
'       xxfnd_ui_pkg.person_name(w.pending_user) as pending_name,',
'       case when w.pending_user is not null then to_char(r.last_action_date, ''DD-MON-YYYY HH24:MI'') end as since',
'  from xxcmp_requests r',
' cross apply (select case when r.request_status in (''DRAFT'', ''IN_PROGRESS'', ''INFO_NEEDED'')',
'                          then xxcmp_request_pkg.pending_with(r.request_id) end as pending_user',
'                from dual) w',
' where r.request_id = :P0_REQUEST_ID'))
,p_display_when_condition=>':APP_PAGE_ID in (203, 205, 206) and :P0_REQUEST_ID is not null'
,p_display_when_cond2=>'PLSQL'
,p_display_condition_type=>'EXPRESSION'
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P0_REQUEST_ID'
,p_lazy_loading=>false
,p_query_row_template=>2540130677583398057
,p_query_headings_type=>'NO_HEADINGS'
,p_query_num_rows=>1
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_no_data_found=>'The request is not available.'
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'N'
,p_comment=>'UI/UX standard header card of a request. Release 74: SQL data and the column''s HTML template (kyc-hcard classes); kyc-app.js builds the section menu from the regions under it.'
);
