,p_step_title=>'Party'
,p_first_item=>'AUTO_FIRST_ITEM'
,p_autocomplete_on_off=>'OFF'
,p_group_id=>wwv_flow_imp.id(40778575691336837)
,p_step_template=>4073832297226169690
,p_page_template_options=>'#DEFAULT#'
,p_required_role=>wwv_flow_imp.id(40758515700336774)
,p_protection_level=>'C'
,p_help_text=>'One party, read only: the party, additional information, contact persons, owners / officers and documents (the common Global Page regions). Edit (Parties - Manage) opens the party wizard (Party Information, Party Details, Review); this page is its re'
||'view step. Compliance can merge this party into a similar one.'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(40811870291337234)
,p_plug_name=>'Party'
,p_static_id=>'breadcrumb'
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>2532939663579242476
,p_plug_display_sequence=>10
,p_plug_display_point=>'REGION_POSITION_01'
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_menu_id=>wwv_flow_imp.id(40761413938336805)
,p_plug_source_type=>'NATIVE_BREADCRUMB'
,p_menu_template_id=>4073839682315169711
);
wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(40812159228337234)
,p_name=>'Possible Existing Matches'
,p_static_id=>'matches'
,p_region_name=>'matches'
,p_template=>4073835273271169698
,p_display_sequence=>25
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#:t-Report--stretch:t-Report--horizontalBorders'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- name similarity computed once per party (inline view), not three times',
'select m.party_id,',
'       m.party_number,',
'       m.party_name,',
'       m.registration_number,',
'       xxfnd_util_pkg.lookup_meaning(''JURISDICTION'', m.jurisdiction) as jurisdiction,',
'       case when m.same_registration = ''Y''',
'            then ''Same '' || lower(xxcmp_party_pkg.field_label(m.party_type, ''REGISTRATION_NUMBER''))',
'            else round(m.similarity) || ''% name match''',
'       end as match_reason,',
'       -- Compliance merges this party (the duplicate) into the matched one',
'       case when xxfnd_privilege_pkg.has_privilege(''PARTIES'', ''MANAGE'')',
'                 and xxcmp_party_pkg.is_enabled(:P21_PARTY_ID) = ''Y''',
'            then ''Merge into this party'' end as merge',
'  from (select p.party_id, p.party_number, p.party_name, p.party_type, p.registration_number, p.jurisdiction,',
'               case when p.registration_number is not null',
'                     and upper(replace(p.registration_number, '' '')) = upper(replace(me.registration_number, '' ''))',
'                    then ''Y'' else ''N'' end as same_registration,',
'               xxcmp_party_pkg.name_similarity(p.party_name, me.party_name) as similarity',
'          from xxcmp_parties me',
'          join xxcmp_parties p',
'            on p.party_id <> me.party_id and p.party_type = me.party_type and p.enabled_flag = ''Y''',
'         where me.party_id = :P21_PARTY_ID) m',
' where m.same_registration = ''Y'' or m.similarity >= 85',
' order by m.similarity desc',
' fetch first 10 rows only'))
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P21_PARTY_ID'
,p_lazy_loading=>false
,p_query_row_template=>2540130677583398057
,p_query_num_rows=>10
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_no_data_found=>'No similar parties found.'
,p_query_num_rows_type=>'ROW_RANGES_WITH_LINKS'
,p_pagination_display_position=>'BOTTOM_RIGHT'
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'N'
);
