,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Add attachment'
,p_static_id=>'add-attachment'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'if :P90_DATATYPE_CODE = ''FILE'' then',
'    :P90_ATTACHED_DOCUMENT_ID := xxfnd_attach_pkg.add_file(',
'        p_entity_name    => :P90_ENTITY_NAME,',
'        p_pk1_value      => :P90_PK1_VALUE,',
'        p_category_code  => :P90_CATEGORY_CODE,',
'        p_temp_file_name => :P90_FILE,',
'        p_title          => :P90_TITLE,',
'        p_description    => :P90_DESCRIPTION,',
'        p_document_date  => to_date(:P90_DOCUMENT_DATE),',
'        p_expiry_date    => to_date(:P90_EXPIRY_DATE),',
'        p_page_id        => to_number(:P90_SOURCE_PAGE));',
'else',
'    :P90_ATTACHED_DOCUMENT_ID := xxfnd_attach_pkg.add_text(',
'        p_entity_name   => :P90_ENTITY_NAME,',
'        p_pk1_value     => :P90_PK1_VALUE,',
'        p_category_code => :P90_CATEGORY_CODE,',
'        p_datatype_code => :P90_DATATYPE_CODE,',
'        p_title         => nvl(:P90_TITLE, :P90_URL),',
'        p_text          => :P90_TEXT,',
'        p_url           => :P90_URL,',
'        p_description   => :P90_DESCRIPTION);',
'end if;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(40877392650337508)
,p_process_when=>'xxfnd_attach_pkg.block_permission(:APP_ALIAS, to_number(:P90_SOURCE_PAGE), :P90_SOURCE_REGION, :P90_ENTITY_NAME, ''INSERT'') = ''Y'''
,p_process_when_type=>'EXPRESSION'
