,p_process_name=>'Save Additional Information'
,p_static_id=>'p91-dff-save'
,p_process_sql_clob=>'xxfnd_dff_pkg.save(''XXFND_ATTACHED_DOCUMENTS'', :P91_ATTACHED_DOCUMENT_ID, :P91_DFF_JSON, :P91_DFF_CONTEXT, p_reference_value => :P91_CATEGORY_CODE);'
