,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Cancel the request'
,p_static_id=>'cancel-request'
,p_process_sql_clob=>'xxcmp_request_pkg.cancel(:P201_REQUEST_ID);'
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(40923571570337673)
