,p_region_name=>'respond'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>8
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- the question Compliance asked (the latest comment on the checklist task)',
'declare',
'    l_text varchar2(4000);',
'begin',
'    select max(c.text) keep (dense_rank last order by c.created_on) into l_text',
'      from apex_task_comments c',
'     where c.task_id = :P203_INFO_TASK_ID;',
'    return ''<p>Compliance asked:</p><blockquote>'' || apex_escape.html(nvl(l_text, ''-'')) || ''</blockquote>''',
'           || ''<p>Update the request if needed, then answer here: the request goes back to the approver.</p>'';',
'end;'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_DYNAMIC_CONTENT'
,p_ajax_items_to_submit=>'P203_INFO_TASK_ID'
,p_plug_display_condition_type=>'ITEM_IS_NOT_NULL'
,p_plug_display_when_condition=>'P203_INFO_TASK_ID'
);
