,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Record comment'
,p_static_id=>'add-comment'
,p_process_sql_clob=>'apex_human_task.add_task_comment(p_task_id => :P206_TASK_ID, p_text => :P206_COMMENT);'
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>':P206_COMMENT is not null and :P206_TASK_ID is not null and nvl(:P206_DECISION, ''#'') not in (''SUBMIT_INFO'', ''REQUEST_INFO'')'
,p_process_when_type=>'EXPRESSION'
,p_process_when2=>'PLSQL'
,p_internal_uid=>40940133747337753
);
