wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(40939934032337752)
,p_process_sequence=>8
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'The requester''s open question'
,p_static_id=>'find-info-task'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- release 74: an approver asked the requester for information: the requester answers here (Submit Information)',
':P206_INFO_TASK_ID := nvl(xxfnd_task_pkg.info_task(''DOC_CHECKLIST_REVIEW'', :P206_REQUEST_ID),',
'                          xxcmp_case_pkg.info_task(:P206_REQUEST_ID));',
':P206_INFO_QUESTION := xxfnd_task_pkg.last_comment(:P206_INFO_TASK_ID);'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>40939934032337752
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(40939848242337752)
,p_process_sequence=>7
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'My open task on this request'
,p_static_id=>'find-my-task'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- opened from KYC Requests (not My Tasks): use the approver''s own open task on this request',
'select max(t.task_id) into :P206_TASK_ID',
'  from table ( apex_human_task.get_tasks ( p_context => ''MY_TASKS'', p_application_id => :APP_ID ) ) t',
' where t.detail_pk = :P206_REQUEST_ID',
'   and t.task_def_static_id in (''DOC_CHECKLIST_REVIEW'', ''COUNTERPARTY_MATCH'')',
'   and t.state_code in (''ASSIGNED'', ''UNASSIGNED'');'))
,p_process_clob_language=>'PLSQL'
,p_process_when=>'P206_TASK_ID'
,p_process_when_type=>'ITEM_IS_NULL'
,p_internal_uid=>40939848242337752
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(40940072212337752)
,p_process_sequence=>6
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Load case'
,p_static_id=>'load-case'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select max(case_id) into :P206_CASE_ID from xxcmp_cases where request_id = :P206_REQUEST_ID;',
'-- the breadcrumb shows the request number before the page items are rendered',
'select max(request_number), max(party_id) into :P206_REQUEST_NUMBER, :P206_PARTY_ID',
'  from xxcmp_requests where request_id = :P206_REQUEST_ID;',
'-- the common Party / Approval Path / History regions (Global Page)',
':P0_REQUEST_ID := :P206_REQUEST_ID;',
':P0_SUMMARY_PARTY_ID := :P206_PARTY_ID;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>40940072212337752
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(40939600732337752)
,p_process_sequence=>5
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Merge into existing party'
,p_static_id=>'merge-party'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_party number;',
'begin',
'    select party_id into l_party from xxcmp_requests where request_id = :P206_REQUEST_ID;',
'    xxcmp_party_pkg.merge_parties(l_party, to_number(:P206_MERGE_PARTY_ID), :P206_MATCH_NOTE);',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>'MERGE'
,p_process_when_type=>'REQUEST_IN_CONDITION'
,p_process_success_message=>'The counterparty''s party was merged into the existing party.'
,p_internal_uid=>40939600732337752
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(40939735342337752)
,p_process_sequence=>5
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Open from task'
,p_static_id=>'open-from-task'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_def apex_tasks.task_def_static_id%type;',
'    l_pk  apex_tasks.detail_pk%type;',
'begin',
'    select task_def_static_id, detail_pk into l_def, l_pk',
'      from table ( apex_human_task.get_tasks (',
'                       p_context        => ''SINGLE_TASK'',',
'                       p_task_id        => :P206_TASK_ID,',
'                       p_application_id => :APP_ID ) )',
'     where task_def_static_id in (''DOC_CHECKLIST_REVIEW'', ''COUNTERPARTY_MATCH'', ''CASE_APPROVAL'');',
'    -- release 74: a case approver asked the requester for information: answered on the request',
'    :P206_REQUEST_ID := case when l_def = ''CASE_APPROVAL'' then xxcmp_case_pkg.request_of(to_number(l_pk))',
'                             else to_number(l_pk) end;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_process_when=>'P206_TASK_ID'
,p_process_when_type=>'ITEM_IS_NOT_NULL'
,p_internal_uid=>40939735342337752
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(40940317056337753)
,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Reject request'
,p_static_id=>'reject-task'
,p_process_sql_clob=>'apex_human_task.reject_task(p_task_id => :P206_TASK_ID, p_autoclaim => true);'
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>':REQUEST = ''CONFIRM'' and :P206_DECISION = ''REJECT'''
,p_process_when_type=>'EXPRESSION'
,p_process_when2=>'PLSQL'
,p_process_success_message=>'Request rejected.'
,p_internal_uid=>40940317056337753
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(40940457107337753)
,p_process_sequence=>40
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Request information'
,p_static_id=>'request-info-task'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- the question goes to the requester (task initiator); an unclaimed task is claimed first',
'for t in (select 1 from apex_tasks where task_id = :P206_TASK_ID and state_code = ''UNASSIGNED'') loop',
'    apex_human_task.claim_task(p_task_id => :P206_TASK_ID);',
'end loop;',
'if xxcmp_request_pkg.can_request_info(:P206_TASK_ID) = ''N'' then',
'    -- release 73: the approver is the requester (APEX cannot ask the initiator from the initiator):',
'    -- the request goes back to the requester with the question; resubmitting starts the approval again',
'    xxcmp_request_pkg.return_for_info(:P206_REQUEST_ID, :P206_TASK_ID, :P206_COMMENT);',
'else',
'    apex_human_task.request_more_information(p_task_id => :P206_TASK_ID, p_text => :P206_COMMENT);',
'end if;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>':REQUEST = ''CONFIRM'' and :P206_DECISION = ''REQUEST_INFO'''
,p_process_when_type=>'EXPRESSION'
,p_process_when2=>'PLSQL'
,p_process_success_message=>'Information requested: the requester answers, then the request comes back for approval.'
,p_internal_uid=>40940457107337753
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(40940604098337753)
,p_process_sequence=>60
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Submit information'
,p_static_id=>'submit-info'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- the task goes back to the approver; the request is In Progress again (task action)',
'apex_human_task.submit_information(p_task_id => :P206_INFO_TASK_ID, p_text => :P206_COMMENT);'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>':REQUEST = ''CONFIRM'' and :P206_DECISION = ''SUBMIT_INFO'' and :P206_INFO_TASK_ID is not null'
,p_process_when_type=>'EXPRESSION'
,p_process_when2=>'PLSQL'
,p_process_success_message=>'Information submitted: the request is back with the approver.'
,p_internal_uid=>40940604098337753
);
end;
/
