wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(40955321808337830)
,p_name=>'E-mails'
,p_static_id=>'emails'
,p_region_name=>'emails'
,p_template=>4073835273271169698
,p_display_sequence=>72
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#:t-Report--stretch:t-Report--horizontalBorders'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- release 74 (R27): e-mails with outside people kept with the record (COMMON XXFND_COMMUNICATIONS)',
'select c.communication_id,',
'       case c.direction when ''OUT'' then ''Sent'' else ''Received'' end as direction,',
'       case c.direction when ''OUT'' then c.to_address || nvl2(c.cc_address, '' (cc '' || c.cc_address || '')'', null)',
'            else c.from_address end as counterpart,',
'       c.subject,',
'       dbms_lob.substr(c.body, 600, 1) as body_text,',
'       xxfnd_util_pkg.lookup_meaning(''COMMUNICATION_STATUS'', c.status) as status,',
'       case c.status when ''SENT'' then ''success'' when ''RECEIVED'' then ''info'' when ''FAILED'' then ''danger'' else ''warning'' end as status_tone,',
'       to_char(c.communication_date, ''DD-MON-YYYY HH24:MI'') as sent_on,',
'       c.communication_date,',
'       xxfnd_ui_pkg.person_name(c.recorded_by) as recorded_by,',
'       (select count(*) from xxfnd_attached_documents_v a',
'         where a.entity_name = ''XXFND_COMMUNICATIONS'' and a.pk1_value = to_char(c.communication_id)) as attachments',
'  from xxfnd_communications c',
' where c.entity_name = ''XXCMP_CASES'' and c.pk1_value = to_char(:P211_CASE_ID)'))
,p_display_when_condition=>':P211_SECTION in (''NOTES'', ''REVIEW'') and xxfnd_privilege_pkg.has_privilege(''CASES'', ''VIEW'')'
,p_display_when_cond2=>'PLSQL'
,p_display_condition_type=>'EXPRESSION'
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P211_CASE_ID'
,p_lazy_loading=>false
,p_query_row_template=>2540130677583398057
,p_query_num_rows=>50
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_no_data_found=>'No e-mails yet.'
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'N'
,p_comment=>'Release 74 (R27): e-mails sent to or received from outside people, kept with the record; sent through APEX mail now, Outlook later.'
);
