wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(40956520883337830)
,p_name=>'Risk Score &P211_RISK_SCORE_TEXT.'
,p_static_id=>'risk-score'
,p_region_name=>'risk_score'
,p_template=>4073835273271169698
,p_display_sequence=>54
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#:t-Report--stretch:t-Report--horizontalBorders'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- release 74 (R16): how the risk score is made up - live (approved model) while the case is investigated,',
'-- as kept at submission once it is with the approvers',
'select rownum as seq, x.factor_name, x.detail, x.points, x.force_tier',
'  from (select j.factor_name, j.detail, j.points, j.force_tier',
'          from json_table(xxcmp_risk_pkg.breakdown_json(to_number(:P211_CASE_ID)), ''$[*]''',
'                   columns (factor_name varchar2(200)  path ''$.factor_name'',',
'                            detail      varchar2(1000) path ''$.detail'',',
'                            points      number         path ''$.points'',',
'                            force_tier  varchar2(30)   path ''$.force_tier'')) j',
'         where xxcmp_case_pkg.is_editable(:P211_CASE_ID) = ''Y''',
'        union all',
'        select f.factor_name, s.detail, s.points, s.force_tier',
'          from xxcmp_case_risk_scores s',
'          left join xxcmp_risk_factors f on f.factor_code = s.factor_code',
'         where s.case_id = :P211_CASE_ID and xxcmp_case_pkg.is_editable(:P211_CASE_ID) = ''N'') x'))
,p_display_when_condition=>':P211_SECTION in (''RISK'', ''REVIEW'')'
,p_display_when_cond2=>'PLSQL'
,p_display_condition_type=>'EXPRESSION'
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P211_CASE_ID'
,p_lazy_loading=>false
,p_query_row_template=>2540130677583398057
,p_query_num_rows=>50
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_no_data_found=>'No risk factor applies.'
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'N'
,p_comment=>'Release 74 (R16): the configurable risk model (page 167) suggests the tier; the officer still classifies the case.'
);
