,p_process_sequence=>20
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Risk score and suggested tier'
,p_static_id=>'risk-score-text'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- release 74 (R16): the region title - total score, the tier the model suggests, the officer''s tier',
'declare',
'    l_tier varchar2(30) := xxcmp_risk_pkg.suggested_tier(:P211_CASE_ID);',
'    l_case varchar2(30);',
'begin',
'    select max(risk_tier) into l_case from xxcmp_cases where case_id = :P211_CASE_ID;',
unistr('    :P211_RISK_SCORE_TEXT := xxcmp_risk_pkg.score(:P211_CASE_ID) || '' \00B7 suggested tier '''),
'        || nvl(xxfnd_util_pkg.lookup_meaning(''RISK_TIER'', l_tier), ''-'')',
'        || case when l_case is not null and l_case <> nvl(l_tier, ''#'')',
unistr('                then '' \00B7 classified '' || xxfnd_util_pkg.lookup_meaning(''RISK_TIER'', l_case) end;'),
'end;'))
,p_process_clob_language=>'PLSQL'
,p_process_when=>':P211_SECTION in (''RISK'', ''REVIEW'')'
,p_process_when_type=>'EXPRESSION'
,p_process_when2=>'PLSQL'
,p_internal_uid=>40968114511337864
);
