begin
wwv_flow_imp.g_varchar2_table := wwv_flow_imp.empty_varchar2_table;
wwv_flow_imp.g_varchar2_table(1) := '--------------------------------------------------------------------------------'||wwv_flow.LF||
'-- 03 Use the share';
wwv_flow_imp.g_varchar2_table(2) := 'd schema (release 54; release 57: the one-time move is an ADMIN script). KYC only; runs on install a';
wwv_flow_imp.g_varchar2_table(3) := 'nd'||wwv_flow.LF||
'-- on every upgrade.'||wwv_flow.LF||
'--   The shared XXFND_ objects live only in XXFUSION (the COMMON application';
wwv_flow_imp.g_varchar2_table(4) := '''s schema). This schema keeps its'||wwv_flow.LF||
'--   own XXCMP_ objects and reaches the shared ones through synony';
wwv_flow_imp.g_varchar2_table(5) := 'ms; XXFUSION grants what is needed'||wwv_flow.LF||
'--   (XXFND_SHARE_PKG, COMMON script 19c). The COMMON application';
wwv_flow_imp.g_varchar2_table(6) := ' must be installed / upgraded first.'||wwv_flow.LF||
'--   - A synonym for every shared object (new objects of later ';
wwv_flow_imp.g_varchar2_table(7) := 'releases too).'||wwv_flow.LF||
'--   - Data security policies use XXFUSION.XXFND_VPD_PKG.'||wwv_flow.LF||
'--   While XXCUS still has ';
wwv_flow_imp.g_varchar2_table(8) := 'its own copy of the shared data it installs nothing and reports ORA-20903: run the one-time'||wwv_flow.LF||
'--   ADM';
wwv_flow_imp.g_varchar2_table(9) := 'IN script apex/db/admin/move-kyc-shared-data-to-xxfusion.sql first.'||wwv_flow.LF||
'-- Idempotent.'||wwv_flow.LF||
'-----------------';
wwv_flow_imp.g_varchar2_table(10) := '---------------------------------------------------------------'||wwv_flow.LF||
'declare'||wwv_flow.LF||
'    c_shared constant varcha';
wwv_flow_imp.g_varchar2_table(11) := 'r2(128) := ''XXFUSION'';'||wwv_flow.LF||
'    l_n      pls_integer;'||wwv_flow.LF||
'begin'||wwv_flow.LF||
'    select count(*) into l_n from all_objects';
wwv_flow_imp.g_varchar2_table(12) := ''||wwv_flow.LF||
'     where owner = c_shared and object_name = ''XXFND_SHARE_PKG'' and object_type = ''PACKAGE'';'||wwv_flow.LF||
'    if';
wwv_flow_imp.g_varchar2_table(13) := ' l_n = 0 then'||wwv_flow.LF||
'        raise_application_error(-20902,'||wwv_flow.LF||
'            ''ACTION NEEDED - the shared object';
wwv_flow_imp.g_varchar2_table(14) := 's are not available in '' || c_shared || ''. Nothing was installed.'' || chr(10)'||wwv_flow.LF||
'            || ''1. Imp';
wwv_flow_imp.g_varchar2_table(15) := 'ort the COMMON application (same release, parsing schema '' || c_shared'||wwv_flow.LF||
'            || '', Install Sup';
wwv_flow_imp.g_varchar2_table(16) := 'porting Objects: Yes).'' || chr(10)'||wwv_flow.LF||
'            || ''2. Come back: App Builder > KYC > Utilities > Sup';
wwv_flow_imp.g_varchar2_table(17) := 'porting Objects > Install Supporting Objects (or Upgrade).'');'||wwv_flow.LF||
'    end if;'||wwv_flow.LF||
''||wwv_flow.LF||
'    select count(*) into ';
wwv_flow_imp.g_varchar2_table(18) := 'l_n from user_tables where table_name in (''XXFND_LOOKUP_TYPES'', ''XXCMP_SHARED_FKS'');'||wwv_flow.LF||
'    if l_n > 0 ';
wwv_flow_imp.g_varchar2_table(19) := 'then'||wwv_flow.LF||
'        raise_application_error(-20903,'||wwv_flow.LF||
'            ''ACTION NEEDED - XXCUS still has its own co';
wwv_flow_imp.g_varchar2_table(20) := 'py of the shared data. Nothing was installed.'' || chr(10)'||wwv_flow.LF||
'            || ''1. Run apex/db/admin/move-';
wwv_flow_imp.g_varchar2_table(21) := 'kyc-shared-data-to-xxfusion.sql once as ADMIN (it validates first, then moves).'''||wwv_flow.LF||
'            || chr(';
wwv_flow_imp.g_varchar2_table(22) := '10)'||wwv_flow.LF||
'            || ''2. Come back: App Builder > KYC > Utilities > Supporting Objects > Install Suppo';
wwv_flow_imp.g_varchar2_table(23) := 'rting Objects (or Upgrade).'');'||wwv_flow.LF||
'    end if;'||wwv_flow.LF||
''||wwv_flow.LF||
'    for o in (select object_name from all_objects'||wwv_flow.LF||
'      ';
wwv_flow_imp.g_varchar2_table(24) := '         where owner = c_shared and object_name like ''XXFND\_%'' escape ''\'''||wwv_flow.LF||
'                 and obje';
wwv_flow_imp.g_varchar2_table(25) := 'ct_type in (''TABLE'', ''VIEW'', ''SEQUENCE'', ''PACKAGE'', ''TYPE'', ''PROCEDURE'', ''FUNCTION'')'||wwv_flow.LF||
'               ';
wwv_flow_imp.g_varchar2_table(26) := '  and object_name not in (''XXFND_SCHEMA_RELEASES'', ''XXFND_DDL_PKG'')) loop'||wwv_flow.LF||
'        select count(*) in';
wwv_flow_imp.g_varchar2_table(27) := 'to l_n from user_objects where object_name = o.object_name;'||wwv_flow.LF||
'        if l_n = 0 then'||wwv_flow.LF||
'            exec';
wwv_flow_imp.g_varchar2_table(28) := 'ute immediate ''create synonym '' || o.object_name || '' for '' || c_shared || ''.'' || o.object_name;'||wwv_flow.LF||
'   ';
wwv_flow_imp.g_varchar2_table(29) := '     end if;'||wwv_flow.LF||
'    end loop;'||wwv_flow.LF||
''||wwv_flow.LF||
'    execute immediate ''begin xxfnd_schema_pkg.apply_policies; end;'';'||wwv_flow.LF||
'   ';
wwv_flow_imp.g_varchar2_table(30) := ' commit;'||wwv_flow.LF||
'end;'||wwv_flow.LF||
'/'||wwv_flow.LF||
'';
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(40779732529336838)
,p_install_id=>wwv_flow_imp.id(40779300550336837)
,p_name=>'03-use-the-shared-schema'
,p_sequence=>3
,p_script_type=>'INSTALL'
