begin
wwv_flow_imp.g_varchar2_table := wwv_flow_imp.empty_varchar2_table;
wwv_flow_imp.g_varchar2_table(1) := '--------------------------------------------------------------------------------'||wwv_flow.LF||
'-- 16u0 Risk model ';
wwv_flow_imp.g_varchar2_table(2) := '- package specification (release 74, R16). KYC only (XXCUS).'||wwv_flow.LF||
'--   The specification runs before 16s ';
wwv_flow_imp.g_varchar2_table(3) := '(the case package uses it: the risk score on submit, the review interval); the'||wwv_flow.LF||
'--   tables, the body';
wwv_flow_imp.g_varchar2_table(4) := ' and the seed are 16u. The specification uses no table.'||wwv_flow.LF||
'-- Idempotent: create or replace only.'||wwv_flow.LF||
'-----';
wwv_flow_imp.g_varchar2_table(5) := '---------------------------------------------------------------------------'||wwv_flow.LF||
'create or replace packag';
wwv_flow_imp.g_varchar2_table(6) := 'e xxcmp_risk_pkg authid definer as'||wwv_flow.LF||
'    -- The risk model (business-maintained, maker-checker): facto';
wwv_flow_imp.g_varchar2_table(7) := 'rs with points (XXCMP_RISK_FACTORS), country lists'||wwv_flow.LF||
'    -- such as the FATF black and grey lists (XXC';
wwv_flow_imp.g_varchar2_table(8) := 'MP_RISK_COUNTRIES) and tier thresholds with review intervals'||wwv_flow.LF||
'    -- (XXCMP_RISK_TIERS). Every row ke';
wwv_flow_imp.g_varchar2_table(9) := 'eps its last approved values: the APPROVED model scores the cases; the PROPOSED'||wwv_flow.LF||
'    -- model (the va';
wwv_flow_imp.g_varchar2_table(10) := 'lues being changed) is used only to preview the impact of a change.'||wwv_flow.LF||
'    c_approved constant varchar2';
wwv_flow_imp.g_varchar2_table(11) := '(10) := ''APPROVED'';'||wwv_flow.LF||
'    c_proposed constant varchar2(10) := ''PROPOSED'';'||wwv_flow.LF||
''||wwv_flow.LF||
'    -- The score of a case ';
wwv_flow_imp.g_varchar2_table(12) := 'and the factors behind it: JSON array [{"factor_code","factor_name","detail","points",'||wwv_flow.LF||
'    -- "force';
wwv_flow_imp.g_varchar2_table(13) := '_tier"}]. P_MODEL: APPROVED (default) or PROPOSED.'||wwv_flow.LF||
'    function breakdown_json(p_case_id in number, ';
wwv_flow_imp.g_varchar2_table(14) := 'p_model in varchar2 default ''APPROVED'') return clob;'||wwv_flow.LF||
'    function score(p_case_id in number, p_model';
wwv_flow_imp.g_varchar2_table(15) := ' in varchar2 default ''APPROVED'') return number;'||wwv_flow.LF||
'    -- The risk tier the model suggests for the case';
wwv_flow_imp.g_varchar2_table(16) := ' (the thresholds; a factor may force a tier, e.g. FATF black list).'||wwv_flow.LF||
'    function suggested_tier(p_ca';
wwv_flow_imp.g_varchar2_table(17) := 'se_id in number, p_model in varchar2 default ''APPROVED'') return varchar2;'||wwv_flow.LF||
'    -- Calculates the case';
wwv_flow_imp.g_varchar2_table(18) := ' with the approved model and keeps the breakdown (XXCMP_CASE_RISK_SCORES) - on submit for'||wwv_flow.LF||
'    -- app';
wwv_flow_imp.g_varchar2_table(19) := 'roval and on Recalculate.'||wwv_flow.LF||
'    procedure calculate(p_case_id in number);'||wwv_flow.LF||
'    -- Review interval (mont';
wwv_flow_imp.g_varchar2_table(20) := 'hs) of a tier in the approved model (the RISK_TIER lookup tag when not set).'||wwv_flow.LF||
'    function review_mon';
wwv_flow_imp.g_varchar2_table(21) := 'ths(p_risk_tier in varchar2) return number;'||wwv_flow.LF||
'    -- Impact of the proposed changes (R24): the open ca';
wwv_flow_imp.g_varchar2_table(22) := 'ses whose suggested tier would change. JSON array'||wwv_flow.LF||
'    -- [{"case_id","case_number","party_name","cur';
wwv_flow_imp.g_varchar2_table(23) := 'rent_score","current_tier","proposed_score","proposed_tier"}].'||wwv_flow.LF||
'    function impact_json return clob;';
wwv_flow_imp.g_varchar2_table(24) := ''||wwv_flow.LF||
'    -- Y while risk model changes wait to be submitted or approved.'||wwv_flow.LF||
'    function has_pending_change';
wwv_flow_imp.g_varchar2_table(25) := 's return varchar2;'||wwv_flow.LF||
'    -- Submits the changed rows of the model for approval (one approval task per ';
wwv_flow_imp.g_varchar2_table(26) := 'table that has changes).'||wwv_flow.LF||
'    procedure submit_changes;'||wwv_flow.LF||
'end xxcmp_risk_pkg;'||wwv_flow.LF||
'/'||wwv_flow.LF||
'';
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(40780356821336854)
,p_install_id=>wwv_flow_imp.id(40779300550336837)
,p_name=>'16u0-kyc-risk-model-package-specification'
,p_sequence=>161
,p_script_type=>'INSTALL'
,p_condition_type=>'EXISTS'
,p_condition=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select 1 from all_objects where owner = ''XXFUSION'' and object_name = ''XXFND_SHARE_PKG''',
'   and not exists (select 1 from user_tables',
'                    where table_name in (''XXFND_LOOKUP_TYPES'', ''XXCMP_SHARED_FKS''))'))
,p_script_clob=>wwv_flow_imp.varchar2_to_clob(wwv_flow_imp.g_varchar2_table)
