begin
wwv_flow_imp.g_varchar2_table := wwv_flow_imp.empty_varchar2_table;
wwv_flow_imp.g_varchar2_table(1) := '--------------------------------------------------------------------------------'||wwv_flow.LF||
'-- 19a Grants to th';
wwv_flow_imp.g_varchar2_table(2) := 'e shared schema (release 54). KYC only; install and every upgrade.'||wwv_flow.LF||
'--   The shared code in XXFUSION ';
wwv_flow_imp.g_varchar2_table(3) := 'works on registered KYC objects with owner-qualified dynamic SQL'||wwv_flow.LF||
'--   (xxfnd_util_pkg.qualified): ap';
wwv_flow_imp.g_varchar2_table(4) := 'provals and flexfields update XXCMP_ tables, Config Change Approvals read'||wwv_flow.LF||
'--   XXCMP_CONFIG_CHANGES_';
wwv_flow_imp.g_varchar2_table(5) := 'V, the flexfield views read the tables, user renames update the user-name columns,'||wwv_flow.LF||
'--   the party-de';
wwv_flow_imp.g_varchar2_table(6) := 'tails authorization calls XXCMP_PARTY_PKG.'||wwv_flow.LF||
'---------------------------------------------------------';
wwv_flow_imp.g_varchar2_table(7) := '-----------------------'||wwv_flow.LF||
'begin'||wwv_flow.LF||
'    for o in (select object_name, object_type from user_objects'||wwv_flow.LF||
'      ';
wwv_flow_imp.g_varchar2_table(8) := '         where object_name like ''XXCMP\_%'' escape ''\'' and object_type in (''TABLE'', ''VIEW'', ''PACKAGE''';
wwv_flow_imp.g_varchar2_table(9) := ')'||wwv_flow.LF||
'               order by object_type, object_name) loop'||wwv_flow.LF||
'        begin'||wwv_flow.LF||
