'                              || o.object_name || '' to xxfusion'';'||wwv_flow.LF||
'     ';
wwv_flow_imp.g_varchar2_table(13) := '   exception'||wwv_flow.LF||
'            when others then'||wwv_flow.LF||
'                -- an invalid view cannot be granted; it i';
wwv_flow_imp.g_varchar2_table(14) := 's granted on the next run'||wwv_flow.LF||
'                dbms_output.put_line(''skipped '' || o.object_name || '': '' |';
wwv_flow_imp.g_varchar2_table(15) := '| sqlerrm);'||wwv_flow.LF||
'        end;'||wwv_flow.LF||
'    end loop;'||wwv_flow.LF||
'end;'||wwv_flow.LF||
'/'||wwv_flow.LF||
'';
