 p_id=>wwv_flow_imp.id(40779487618336838)
,p_install_id=>wwv_flow_imp.id(40779300550336837)
,p_name=>'DBMS_CRYPTO granted'
,p_sequence=>10
,p_check_type=>'FUNCTION_BODY'
,p_check_condition=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Runs the check as the parsing schema itself, the way the packages will use it.',
'declare',
'    l_type pls_integer;',
'begin',
'    execute immediate ''begin :t := dbms_crypto.hash_sh256; end;'' using out l_type;',
'    return true;',
'exception',
'    when others then',
'        return false;',
'end;'))
,p_check_condition2=>'PLSQL'
,p_failure_message=>'Ask the database administrator to run: grant execute on dbms_crypto to <parsing schema>'
);
wwv_flow_imp_shared.create_install_check(
 p_id=>wwv_flow_imp.id(40779531398336838)
,p_install_id=>wwv_flow_imp.id(40779300550336837)
,p_name=>'DBMS_RLS granted'
,p_sequence=>20
,p_check_type=>'FUNCTION_BODY'
,p_check_condition=>wwv_flow_string.join(wwv_flow_t_varchar2(
